/*
 * Gets called with a sequence of bytes for transmitting over the UART
 */
void serial_adapter_PI_bytearray_tx( const asn1SccByte_Array * pByteArray)
{
    unsigned int aBuff;   // Under the hood TASTE is defaulting to using four bytes for a T-Uint8. Using an unsigned long here to match that default.
    for (size_t i=0; i<pByteArray->nCount; i++)
    {
        aBuff = pByteArray->arr[i];
        serial_adapter_RI_uart_byte_tx(&aBuff);
    }
}


/*
 * Gets called for each byte received over UART. Currently does nothing other than
 * relay the byte out of the other end.
 */
void serial_adapter_PI_uart_byte_rx( const asn1SccT_UInt8 * pByte)
{
    serial_adapter_RI_uart_byte_tx(pByte);
}


/*
 * Convenience function fore transmitting raw strings over UART, without
 * first converting them to a Byte-Array.
 */
void serial_adapter_PI_charbuff_tx( const asn1SccT_UInt8 * pString )
{
    // Iterate over characters in the buffer, sending them one at time via the RI
    for (size_t i=0; i<strlen(pString); i++)
    {
        serial_adapter_RI_uart_byte_tx(pString+i);
    }
}



